import z3

def solve():
    # 20 vertices
    N = 20

    # edges
    E = [[z3.Bool(f"e_{i}_{j}") for j in range(N)] for i in range(N)]

    s = z3.Solver()

    # undirected, no self loops
    for i in range(N):
        s.add(z3.Not(E[i][i]))
        for j in range(i + 1, N):
            s.add(E[i][j] == E[j][i])

    # degree at least 5
    for i in range(N):
        s.add(z3.Sum([z3.If(E[i][j], 1, 0) for j in range(N)]) >= 5)

    # chromatic number at most 3
    # color of each vertex
    C = [z3.Int(f"c_{i}") for i in range(N)]
    for i in range(N):
        s.add(C[i] >= 0, C[i] <= 2)

    # adjacent vertices have different colors
    for i in range(N):
        for j in range(i + 1, N):
            s.add(z3.Implies(E[i][j], C[i] != C[j]))

    # max clique size at most 3 is automatically satisfied if chromatic number <= 3

    if s.check() == z3.sat:
        m = s.model()
        edges = []
        for i in range(N):
            for j in range(i + 1, N):
                if z3.is_true(m[E[i][j]]):
                    edges.extend([i, j])
        print(edges)
    else:
        print("UNSAT")

solve()
